import re


class StackUnderflowError(Exception):
    pass


_NUMBER_RE = re.compile(r"-?\d+$")


def _pop(stack):
    if not stack:
        raise StackUnderflowError("Insufficient number of items in stack")
    return stack.pop()


def _div(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    # Integer division truncating toward zero, like Forth's /
    q, r = divmod(a, b)
    if r and (a < 0) != (b < 0):
        q += 1
    return q


_BUILTINS = {
    "+": lambda s: s.append(_pop(s) + _pop(s)),
    "-": lambda s: s.append(_pop(s) - _pop(s)),
    "*": lambda s: s.append(_pop(s) * _pop(s)),
    "/": lambda s: s.append(_div(_pop(s), _pop(s))),
    "dup": lambda s: s.append(_pop(s)) or s.append(s[-1]),
    "drop": lambda s: _pop(s),
    "swap": lambda s: (s.append(_pop(s)), s.append(_pop(s))),
    "over": lambda s: s.append(s[-2]) if len(s) >= 2 else _pop(s),
}


def evaluate(input_data):
    stack = []
    words = {}

    def execute(tokens):
        for token in tokens:
            token = token.lower()
            if token in words:
                execute(words[token])
            elif token in _BUILTINS:
                _BUILTINS[token](stack)
            else:
                raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.split()
        if tokens and tokens[0] == ":":
            name = tokens[1].lower()
            if _NUMBER_RE.match(name):
                raise ValueError("illegal operation")
            words[name] = tokens[2:-1]
        else:
            execute(tokens)

    return stack

